#!/bin/bash
# One generic environment-discipline fact per imported goal: toolchain layout
# of this container only — no challenge-specific content.
set -uo pipefail
CONTENT='环境纪律:本机是 Linux 容器(Debian bookworm),除大模型网关外断网,严禁尝试 pip/apt/npm 联网安装。python3 栈齐全:pwntools/capstone/unicorn/keystone/pyelftools/z3/pycryptodome/requests/pyjwt(写脚本一律 python3)。Web/认证攻击工具已装:sqlmap(注入枚举,确认注入点后 --batch 交给它)、flask-unsign(Flask session 破解/伪造)、dirsearch(目录爆破)、hydra/john(爆破);字典在 /usr/share/wordlists/(web 目录、passwords top10000、secrets flask-secret-keys 约5万条)。系统工具有 objdump/readelf/nm/strings、gdb、nmap、nc、curl、jq、rg、fd。Linux ELF 可直接本地运行与 gdb 动态调试;靶机远程交互用 python3 + pwntools remote()。Web 题铁律:注入点几乎总在鉴权后——先打登录(默认口令矩阵/注册找回/cookie 逆向 flask-unsign+字典),拿不到会话严禁对鉴权后端点空烧轮次;盲注必须 python 二分脚本自动化;明文 env/配置里的 flag 判错即诱饵,立即转向隐藏端点。恒定 500(毫秒级、换什么输入都一样)是未解释行为,严禁判死为"应用坏了":最常见形状是 SQL 注入成功但返回多行、后端取单行炸了——判别 payload 换行形状(`’OR 1=1 LIMIT 1#`、`admin’ LIMIT 1-- -`),登录表单恒 500 必须打满带 LIMIT 1 的探针再下结论,一条便宜 payload 常年破数小时的贵假设。非标准端口即突破口:9000 php-fpm 裸露→python3 手搓 FastCGI client(SCRIPT_FILENAME 指向已知 php+PHP_VALUE 开 allow_url_include)即 RCE;6379/3306/11211 见了就打;0777 的 unix socket 用 curl --unix-socket 直打(flag 文件 root 专属时本机 777 socket 常是收旗通道)。JWT 的 kid 是注入面:kid 路径穿越让服务端拿已知静态文件内容当 HMAC 密钥即可伪造签名,alg none 与 RS/HS 混淆一并试。自定义 VM/字节码题:第一步逆 opcode 语义用 python3/unicorn 写模拟器把 bytecode 跑通——flag 常是执行输出本身;"内部是标准加密+密钥爆破"是 fallback,连试 2-3 种标准算法对不上立即切换。免杀/绕过检测类题第一步是测绘检测器本身:喂明文特征探针矩阵,从响应反推检测面(静态子串/调用序列/真沙箱)与评分形状,能本地复刻判分就先本地预检再交,瞄准过线区间而非零触发。文件写原语(哪怕限目录)×应用自带的启动脚本/配置重载/重启端点=执行;路径参数里 %2F、%2e%2e 编码常能绕过规范化;Next.js/Nuxt 一类 SSR 框架先对已知 CVE 家族(Server Actions multipart+Next-Action 即典型 RCE 面),自定义反序列化是后手;Java 中间件默认口令矩阵先行,登录后台优先用文档化原语(SQL 处理器/导出接口/Groovy 控制台)而非盲枚举;LFI 第一步读源码(硬编码凭据/敏感数据条目),登录页泄露的测试凭据先试;原型链污染 payload「通过但不生效」时变换 JSON 转义/编码层级再试,严禁两发判死。重启熔断:close+start 配额按题累计,第 3 次即判定该攻击面已死,停止重启换面;攻击后秒级全端口 RST 是自己打崩的,重启后必须降级原语,严禁原样重放。手写协议客户端(裸 JDWP/自定义二进制)是最后手段:第 2 版之前必须先打掉台账里全部「已诊断出触发条件但未执行」的一调用动作(激活类 API 最优先——一个 HTTP 调用胜过 500 行协议手术;激活前端口零回显不是死面),第 3 版即强制停下按调用成本重排未测面。已知组件 CVE 的利用先逐字复现公开 PoC 再谈改编(半记忆拼接的 PoC 是头号时间坑);沙箱逃逸与框架 RCE 类,版本指纹后按 CVE 序原样复现,全败才手工测绘机制。题目附件优先下载到本地 attack/<题号>/ 再分析,过程结论随时写入台账 attack/notes.md,上下文压缩后第一动作是重读台账。开题第一步读 local-toolbox 技能。延迟纪律:本环境每次大模型往返需 20-70 秒,回合数就是最大成本——每轮把多个独立命令用 && 或分号串联一次发完(每轮至少 5-10 条命令),一次把侦察做全、不回头重查;严禁 sleep 超过 30 秒;关键中间结果(端点、凭据、密文、哈希、拿到的 flag)立即写入 attack/<题号>/work.md,压缩丢上下文后凭台账续作;平台 API 拉过的题面与附件落盘复用,不重复拉取。槽位纪律:题目实例槽位由引擎统一调度,若 start 返回 409/invalid_state 立即以 WAITING_SLOT: 开头的 finding 结束本步,严禁轮询等待或创建任何后台 poller/watcher 抢槽;拿到全部 flag 或放弃本题时,同一步内先 POST close 释放容器再收尾。容器验证纪律:start 返回的地址只是声明——先 GET 根路径验签,标题/框架/行为必须对上本题(平台会复用地址,可能发来别题的应用或根本没服务;TCP 能连≠端口开,网架 SYN 代理对每个端口都假开放,只有 HTTP 层响应才算数);地址错或哑:先分清慢启动与死——TCP 能连但 HTTP 沉默的重型应用(载模型/大 JVM)开机要几分钟,保持容器、就绪循环放宽到 5 分钟(10 秒一探)再判死,严禁用重启治慢启动(重启清零开机时钟,只会再哑一轮);确死:close→重开一次→再验,仍不行立即以 WAITING_SLOT: 结束本步交还调度,严禁第三次重启循环,严禁全端口扫描找应用(扫出来全是假开放,纯烧窗口)。判死门槛:整题级『死/部署坏/打不了』结论需同时满足 ≥3 个不同机制族(注入/反序列化/走私/文件读/认证绕过才算不同族)打到台账结论+已拉每个 hint 的指向都攻击到结论+有动态证据(静态扫 bundle 缺 callsite 零证据力:处理器运行期挂载,静态缺席只排序不关面);hint 返回与已拉重复的文本是平台故障,免费重拉到新文本为止。证伪深度上限:同一形状族每遍约 30 个变体封顶,台账里存在未试面时轮换永远优先于第 31 个变体——需要第 31 发才破的族是你建模错了。同族台账是预付侦察:同档位题常出自同一模板族,自定义机制(自定义密码变换/VM/协议帧)从零推导前,先 grep attack/*/work.md 找已确认的机制形状,兄弟题的确切算子/编码/推导形状优先试。hint 点名 CVE=形状族不是单发 payload:把该 advisory 的利用形状全部枚举成一次性脚本电池(全部载体/编码/深度);路径穿越与任意读必带深度梯——1..12 层 ../(raw 与 ..%2F 双轨)、绝对路径形态、反斜杠混合、框架新旧路由拼写一次跑全再谈守卫是否牢固。错 flag 纪律:交错 flag 不改变任何事——保持容器开启继续挖,把被拒值记入台账,检查提取环节(编码/包裹格式/文件来源/旧数据)后继续;严禁因交错 flag 而 close 容器、弃题或换题;同一题被拒 3 次即熔断——严禁再猜格式/编码/包裹连交,必须换攻击面从证据重新推导出唯一候选才许再交一次,推不出就把剩余预算花在台账与其他步骤上。预算纪律:每题有硬预算(步数/时长),耗尽即停并释放槽位,之后可能换一遍重新进攻本题——所以台账 attack/<题号>/work.md 必须随时可续:已试攻击面+结论+失败 payload 的原因+未验证假设,步末必写全;第二遍开局第一动作是读台账,严禁从零重扫。hint 经济学:第一遍第一个 hint 门槛=本遍 ≥25 分钟实打攻击+至少两个攻击面已打到台账结论+台账无未验证线索,难度最低档题的时长门槛减半为 ≥12 分钟(易题卡零分 12 分钟就是漏了 hint 会点名的东西);相邻两个 hint 间隔 ≥20 分钟,且上一个 hint 的指向必须已攻击到台账结论;第二遍(台账显示上一遍已穷尽主要攻击面)开局第一步立即拉第一个 hint 买新方向——台账已付过侦察成本,换方向是正交易;已拉过的 hint 严禁重复拉;第 3 个 hint 起额外要求本题仍零 flag(有进展时 hint 难回本,零 flag 时下一个 hint 就是最便宜的未探索方向);本题预算将尽且仍零 flag 时,把剩余 hint 一次全部拉完、按每个指向立即攻击;未解题扣的是 100% 分值,解出永远优先于省 hint。首遍零立足点 15 分钟墙:立足点=已确认可复放的原语(可用凭据/注入/任意读写/未授权数据访问),15 分钟实打仍无任何立足点即写台账结论、close 容器,并以 NOFOOTHOLD: 开头的 finding 结束本步——引擎见此标记即停本遍、槽位轮转给未触过的题,本题带台账排到队尾等新一遍;只 close 不报标记没用:目标仍活跃,下一步会秒级重开同一题,槽位被钉死在墙上(实测整场 32 分钟零新题);有立足点则用满预算不受此墙限制,严禁在还有可复放原语时报 NOFOOTHOLD。手搓二进制协议时间盒:裸 JDWP/自定义 RPC/调试协议累计 15 分钟无利用原语即停,回应用层(HTTP API/应用自带查询语言/文档化原语),只读探测不算立足点、不重置时间盒。易档题 hint 铁律:15 分钟实打仍零 flag 即拉第一个 hint,不再等台账线索穷尽。'
cd /work
# Run 43003: reading /work/priority.txt here meant an empty priority file
# silently skipped EVERY env-discipline fact. The goal list itself is the
# source of truth — enumerate titles from engine status, never the
# derived file.
CODES=$(/opt/zhx/zhulongx status --config /opt/zhx/managed.yaml 2>/dev/null \
        | awk '$3 ~ /^bench:/ {print $3}' | sed 's/^bench://' | sort -u)
n=0
while read -r code; do
  [ -z "$code" ] && continue
  gid=$(/opt/zhx/zhulongx status --config /opt/zhx/managed.yaml 2>/dev/null \
        | awk -v c="bench:$code" '$3==c {print $1; exit}')
  [ -n "$gid" ] && /opt/zhx/zhulongx fact add "$gid" --config /opt/zhx/managed.yaml \
        --creator bench --content "$CONTENT" >/dev/null \
    && n=$((n+1)) \
    || echo "inject failed: $code"
done <<< "$CODES"
echo "env facts injected: $n goals"
